content.arguments:
{"command": "$tmp = Join-Path $env:TEMP 'cvtest'; New-Item -ItemType Directory -Force -Path $tmp | Out-Null
Get-ChildItem -File -Filter *.pdf | ForEach-Object {
  $out = Join-Path $tmp ($_.BaseName + '.txt')
  & pdftotext -layout $_.FullName $out 2>$null
  $len = if (Test-Path $out) { (Get-Item $out).Length } else { 0 }
  $pages = (Select-String -Path $out -Pattern "`f" -AllMatches -ErrorAction SilentlyContinue).Matches.Count
  "{0,-60} chars={1,-8} pagebreaks={2}" -f $_.Name, $len, $pages
}", "description": "Test PDF text extraction on all PDFs"}

