content.arguments:
{"command": "$tmp = Join-Path $env:TEMP 'cvtest'
$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
Get-ChildItem -File -Filter *.docx | ForEach-Object {
  try {
    $doc = $word.Documents.Open($_.FullName, [ref]$false, [ref]$true)
    $txt = $doc.Content.Text
    $out = Join-Path $tmp ($_.BaseName + '.docx.txt')
    Set-Content -Path $out -Value $txt -Encoding UTF8
    "{0,-62} chars={1,-8} words={2,-7} pages={3}" -f $_.Name, $txt.Length, $doc.Words.Count, $doc.ComputeStatistics(2)
    $doc.Close([ref]$false)
  } catch { "FAIL $($_.Name): $($_.Exception.Message)" }
}
$word.Quit()
[System.Runtime.InteropServices.Marshal]::ReleaseComObject($word) | Out-Null", "description": "Extract text from all docx via Word COM", "timeoutMs": 300000}

