{"command": ""=== grep whole workspace for SQLite / Flutter / PhpSpreadsheet / React evidence (source only) ==="
$roots = @('CTRL Stay coding\lib','CTRL Stay coding\pubspec.yaml','VenueVue\flutevue\lib','VenueVue\flutevue\pubspec.yaml','VenueVue\backend','VenueVue\sql','venuevue - Copy\src','venuevue - Copy\package.json','venuevue - Copy\supabase')
foreach ($r in $roots) {
  if (Test-Path $r) {
    $hits = Select-String -Path (Get-ChildItem $r -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.dart','.php','.sql','.yaml','.ts','.tsx','.json','.js' }).FullName -Pattern 'sqflite|PhpSpreadsheet|PhpOffice|mysql|mysqli|PDO|supabase|IndexedDB|idb|flutter' -ErrorAction SilentlyContinue
    $g = $hits | Group-Object { ($_.Matches[0].Value).ToLower() } | ForEach-Object { "$($_.Name)=$($_.Count)" }
    "{0,-34} {1}" -f $r, ($g -join '  ')
  } else { "{0,-34} NOT FOUND" -f $r }
}", "description": "Grep for stack evidence across both apps"}

