content.arguments:
{"command": "$rb = 'C:\$Recycle.Bin\S-1-5-21-3815034255-820720262-2530389398-1001'
"=== top-level deleted items ==="
Get-ChildItem $rb -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '$R*' } | ForEach-Object {
  $kind = if ($_.PSIsContainer) { 'DIR ' } else { 'FILE' }
  $size = if ($_.PSIsContainer) { (Get-ChildItem $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } else { $_.Length }
  "{0} {1,-22} {2,12:N0} bytes  {3}" -f $kind, $_.Name, $size, $_.LastWriteTime
}
"`n=== $I metadata (original paths + deletion time) ==="
Get-ChildItem $rb -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '$I*' } | ForEach-Object {
  $b = [System.IO.File]::ReadAllBytes($_.FullName)
  $orig = [System.Text.Encoding]::Unicode.GetString($b[24..($b.Length-1)]) -replace "`0.*$",''
  $del  = [datetime]::FromFileTime([BitConverter]::ToInt64($b,0))
  "{0}  deleted={1}  orig={2}" -f $_.Name, $del, $orig
}", "description": "Inventory Recycle Bin deleted items and metadata"}

