```dart
// lib/services/sync_service.dart  — contract-aligned replacement
import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:uuid/uuid.dart';           // ADD uuid ^4.5.1 to pubspec.yaml
import '../database_helper.dart';
import '../models/order_model.dart';

class SyncService {
  static const String _base = 'http://192.168.137.1/venuevue_api';
  static const _uuid = Uuid();

  /// Builds the frozen wire envelope. The server rejects anything else.
  static Map<String, dynamic> buildEnvelope(
    OrderModel order,
    List<Map<String, dynamic>> items, {
    required String tabletId,
    required String sessionToken,
  }) {
    return {
      'client_transaction_id': order.clientTransactionId,
      'tablet_id': tabletId,
      'session_token': sessionToken,
      'order': {
        'cash_tendered': order.cashTendered,
        'created_at': order.createdAt.toIso8601String(),
      },
      'items': items
          .map((i) => {'product_id': i['product_id'], 'quantity': i['quantity']})
          .toList(),
    };
  }

  /// POSTs one order. Returns true only on HTTP 200 or 201.
  static Future<bool> syncOrder(
    OrderModel order,
    List<Map<String, dynamic>> items, {
    required String tabletId,
    required String sessionToken,
  }) async {
    try {
      final res = await http
          .post(
            Uri.parse('$_base/sync.php'),
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer $sessionToken',
            },
            body: jsonEncode(
              buildEnvelope(order, items, tabletId: tabletId, sessionToken: sessionToken),
            ),
          )
          .timeout(const Duration(seconds: 10));

      // 200 = idempotent replay, 201 = newly created. Both mean "committed".
      return res.statusCode == 200 || res.statusCode == 201;
    } catch (_) {
      return false;   // network/parse failure — keep the row unsynced
    }
  }

  /// Drains the queue oldest-first with bounded exponential backoff.
  /// NOTE: the previous implementation used `break` on first failure and
  /// ordered by `created_at DESC`, so a single bad row blocked all newer
  /// rows and the queue drained LIFO. Both are fixed here.
  static Future<({int synced, int failed})> drainQueue(
    DatabaseHelper db, {
    required String tabletId,
    required String sessionToken,
    int maxAttempts = 3,
  }) async {
    final pending = await db.getUnsyncedOrders(orderAscending: true);
    int synced = 0, failed = 0;

    for (final order in pending) {
      final items = await db.getOrderItems(order.orderId);
      bool ok = false;

      for (var attempt = 1; attempt <= maxAttempts && !ok; attempt++) {
        ok = await syncOrder(
          order, items,
          tabletId: tabletId,
          sessionToken: sessionToken,
        );
        if (!ok) {
          await Future<void>.delayed(Duration(milliseconds: 250 * (1 << (attempt - 1))));
        }
      }

      if (ok) {
        await db.markOrderSynced(order.orderId);
        synced++;
      } else {
        failed++;   // continue; one poison row must not block the queue
      }
    }
    return (synced: synced, failed: failed);
  }

  /// Reachability probe. The old HEAD-based probe always returned false
  /// because sync.php answers 405 to HEAD. Probe a GET health endpoint.
  static Future<bool> isServerReachable() async {
    try {
      final res = await http
          .get(Uri.parse('$_base/health.php'))
          .timeout(const Duration(seconds: 3));
      return res.statusCode == 200;
    } catch (_) {
      return false;
    }
  }
}
```

