# An inline $...$ span is only treated as math when its body looks like math.
# This prevents PHP variables such as $pdo or a literal price like $69 from
# being swallowed. Real inline math in this document always contains at least
# one of: _ \ { } = or a Greek/math operator.
MATHY = re.compile(r"[_\\{}=]|[\u2264\u2265\u00d7\u03a3\u0394]")


def sub_math(text: str) -> str:
    """Replace $$display$$ and $inline$ math with readable text."""
    text = re.sub(r"\$\$(.+?)\$\$",
                  lambda m: "\n\n@@MATHBLOCK@@" + latex_to_text(m.group(1)) + "@@ENDMATH@@\n\n",
                  text, flags=re.S)

    def inline_math(m):
        body = m.group(1)
        if not MATHY.search(body):
            return m.group(0)          # not math — leave the $ signs alone
        return "@@MATHINLINE@@" + latex_to_text(body) + "@@ENDMATH@@"

    return re.sub(r"\$([^$\n]+?)\$", inline_math, text)


def apply_math_outside_code(raw: str) -> str:
    """Apply sub_math only to segments that are NOT inside fenced code blocks.

    Critical: PHP source in this document contains many $ sigils ($pdo,
    $input, $txnId). Running the math substituter over code would corrupt it.
    """
    segments = []
    buf = []
    in_code = False
    for line in raw.split("\n"):
        if line.startswith("```"):
            if in_code:
                buf.append(line)
                segments.append((True, "\n".join(buf)))
                buf = []
                in_code = False
            else:
                if buf:
                    segments.append((False, "\n".join(buf)))
                    buf = []
                buf.append(line)
                in_code = True
        else:
            buf.append(line)
    if buf:
        segments.append((in_code, "\n".join(buf)))
    return "\n".join(text if is_code else sub_math(text) for is_code, text in segments)


